}
.sub-caption-1 {
  font-family: 'JetBrains Mono', monospace;
  font-size: 15px;
  color: #8b949e;
  margin-top: 14px;
  opacity: 0;
  animation: dropInSub 0.6s cubic-bezier(.22,1,.36,1) 2.4s forwards;
}
.flash-overlay-1 {
  position: absolute;
  inset: 0;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  z-index: 50;
  animation: flashTrigger 1s ease 4.2s forwards;
}
.logo-box-1 {
  width: 260px;
  height: 260px;
  border: 3px dashed rgba(0, 0, 0, 0.3);
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #1a1a1a;
  font-family: 'JetBrains Mono', monospace;
  font-weight: 800;
  font-size: 15px;
  transform: scale(0.5);
  opacity: 0;
  animation: logoPop 0.6s cubic-bezier(.68,-0.4,.27,1.4) 4.35s forwards;
}
@keyframes typeS1 { from { width: 0; } to { width: 100%; } }
