@keyframes slideLeft2 { from { opacity: 0; transform: translateX(-60px); } to { opacity: 1; transform: translateX(0); } }
@keyframes slideRight2 { from { opacity: 0; transform: translateX(60px); } to { opacity: 1; transform: translateX(0); } }
@keyframes slidePaper2 {
  0% { transform:translateX(-80px) rotate(-6deg); opacity:0; }
  35% { transform:translateX(80px) rotate(0deg); opacity:1; }
  75% { transform:translateX(80px) rotate(0deg); opacity:1; }
  100% { transform:translateX(180px) rotate(6deg); opacity:0; }
}
@keyframes glitchBurst2 {
  0%{ opacity:.4; transform:scale(.85) rotate(-6deg); filter:drop-shadow(0 0 10px #4fd1ff); }
  100%{ opacity:1; transform:scale(1.2) rotate(6deg); filter:drop-shadow(0 0 25px #00ff9d) drop-shadow(0 0 35px #ff4d5e); }
}
@keyframes kineticWord2 { to{ opacity:1; filter:blur(0); transform:translateY(0) scale(1); } }

